<script lang="ts">
	import { ArrowLeft, CalendarClock, Check, CircleDot, FolderGit2, GripVertical, Plus, Sparkles } from "@lucide/svelte";
	import { onMount } from "svelte";
	import type { KanbanBoard, KanbanRegistry, KanbanTask, KanbanTaskKind, KanbanTaskStatus } from "../lib/model.ts";

	let { registry, workspaceRoot, onclose, onsave }: { registry: KanbanRegistry; workspaceRoot: string; onclose: () => void; onsave: (registry: KanbanRegistry) => Promise<void> } = $props();
	const columns: Array<{ id: KanbanTaskStatus; label: string; accent: string }> = [
		{ id: "ideas", label: "Ideas", accent: "bg-[#82919a]" }, { id: "planned", label: "Planned", accent: "bg-[#7ca8d7]" }, { id: "ready", label: "Ready", accent: "bg-[#d6e878]" }, { id: "running", label: "Running", accent: "bg-[#86d58a]" }, { id: "waiting", label: "Waiting", accent: "bg-[#e1b967]" }, { id: "review", label: "Review", accent: "bg-[#b791df]" }, { id: "done", label: "Done", accent: "bg-[#70c891]" },
	];
	let selectedBoardId = $state("");
	let selectedTaskId = $state("");
	let boardName = $state("");
	let taskTitle = $state("");
	let draftPrompt = $state("");
	let draggedTaskId = $state("");
	const board = $derived(registry.boards.find((item) => item.id === selectedBoardId) ?? registry.boards[0]);
	const selectedTask = $derived(board?.tasks.find((task) => task.id === selectedTaskId));

	function sampleTask(title: string, status: KanbanTaskStatus, kind: KanbanTaskKind, sequence: number, now: string, root: string): KanbanTask {
		return { id: `task-${crypto.randomUUID()}`, title, prompt: "", workspaceRoot: root, kind, reasoning: "medium", status, targetMinutes: status === "ready" ? 25 : undefined, createdAt: now, updatedAt: now, createdSequence: sequence };
	}
	function starterBoard(name: string, root: string): KanbanBoard {
		const now = new Date().toISOString();
		return { id: `board-${crypto.randomUUID()}`, name, workspaceRoot: root, createdAt: now, updatedAt: now, createdSequence: registry.boards.length + 1, tasks: [sampleTask("Capture the next improvement", "ideas", "research", 1, now, root), sampleTask("Define acceptance criteria", "planned", "review", 2, now, root), sampleTask("Inspect workspace health", "ready", "maintenance", 3, now, root), sampleTask("Choose a review checklist", "review", "review", 4, now, root), sampleTask("Open the Kanban board", "done", "build", 5, now, root)] };
	}
	async function persist(next: KanbanRegistry): Promise<void> { await onsave(next); }
	onMount(() => { if (registry.boards.length === 0) void persist({ version: 1, boards: [starterBoard("Klerm Workspace", workspaceRoot)] }); });
	$effect(() => { if (board && selectedBoardId !== board.id) selectedBoardId = board.id; });
	async function createBoard(): Promise<void> { const name = boardName.trim(); if (!name) return; const next = starterBoard(name, workspaceRoot); await persist({ ...registry, boards: [...registry.boards, next] }); selectedBoardId = next.id; boardName = ""; }
	async function addTask(status: KanbanTaskStatus = "ideas"): Promise<void> { const title = taskTitle.trim(); if (!title || !board) return; const now = new Date().toISOString(); const task = sampleTask(title, status, "build", board.tasks.length + 1, now, board.workspaceRoot); task.prompt = draftPrompt.trim(); await persist({ ...registry, boards: registry.boards.map((item) => item.id === board.id ? { ...item, updatedAt: now, tasks: [...item.tasks, task] } : item) }); taskTitle = ""; draftPrompt = ""; }
	async function moveTask(taskId: string, status: KanbanTaskStatus): Promise<void> { if (!board) return; const now = new Date().toISOString(); await persist({ ...registry, boards: registry.boards.map((item) => item.id !== board.id ? item : { ...item, updatedAt: now, tasks: item.tasks.map((task) => task.id === taskId ? { ...task, status, updatedAt: now } : task) }) }); }
	function kindLabel(kind: KanbanTaskKind): string { return kind === "maintenance" ? "Maintain" : kind[0]!.toUpperCase() + kind.slice(1); }
</script>

<div class="flex min-h-0 flex-col overflow-hidden bg-[radial-gradient(circle_at_45%_-20%,rgba(161,205,94,.11),transparent_36%),#080d11]">
	<header class="flex shrink-0 items-center gap-3 border-b border-[#26323a] bg-[rgba(8,13,17,.8)] px-5 py-3.5 backdrop-blur-xl"><button type="button" aria-label="Back to workspace" class="grid h-9 w-9 place-items-center rounded-xl border border-[#314049] bg-[#11191e] text-[#a7b4b9] transition hover:-translate-x-0.5 hover:border-[#71838d] hover:text-white" onclick={onclose}><ArrowLeft size={15} /></button><div class="min-w-0"><p class="m-0 font-mono text-[8px] tracking-[.16em] text-[#6e8087] uppercase">Work orchestration</p><h1 class="mt-0.5 mb-0 text-[16px] font-semibold tracking-[-.02em] text-[#edf2f3]">Kanban</h1></div><div class="ml-auto flex items-center gap-2 rounded-full border border-[#2d3b42] bg-[#0c1419] px-3 py-1.5"><CircleDot size={11} class="text-[#b9ea78]" /><span class="font-mono text-[8px] text-[#8ca0a3]">{registry.boards.length} saved board{registry.boards.length === 1 ? "" : "s"}</span></div></header>
	<div class="grid min-h-0 flex-1 grid-cols-[238px_minmax(0,1fr)] max-[780px]:grid-cols-1">
		<aside class="min-h-0 border-r border-[#26323a] bg-[#0a1014]/70 p-3 max-[780px]:hidden"><p class="px-1 pt-1 pb-2 font-mono text-[8px] tracking-[.14em] text-[#667980] uppercase">Your Kanbans</p><form class="flex gap-1.5" onsubmit={(event) => { event.preventDefault(); void createBoard(); }}><input bind:value={boardName} maxlength="100" placeholder="New Kanban..." class="h-9 min-w-0 flex-1 rounded-xl border border-[#34434a] bg-[#0d151a] px-2.5 text-[10px] text-[#e7edef] outline-none placeholder:text-[#64767d] focus:border-[#78905f]" /><button type="submit" aria-label="Create Kanban" class="grid h-9 w-9 place-items-center rounded-xl border border-[rgba(190,241,117,.43)] bg-[#3d5b2b] text-[#efffd9] transition hover:brightness-110"><Plus size={14} /></button></form><div class="mt-3 space-y-1">{#each registry.boards as item (item.id)}<button type="button" class={`w-full rounded-xl border p-2.5 text-left transition ${board?.id === item.id ? "border-[rgba(188,237,116,.33)] bg-[linear-gradient(120deg,rgba(90,130,55,.23),rgba(17,29,32,.9))]" : "border-transparent text-[#91a2a8] hover:border-[#2f4148] hover:bg-[#111a1f]"}`} onclick={() => selectedBoardId = item.id}><span class="block truncate text-[10px] font-semibold text-[#dbe5e7]">{item.name}</span><span class="mt-1 flex items-center gap-1 truncate font-mono text-[7px] text-[#6f8389]"><FolderGit2 size={9} /> {item.workspaceRoot}</span><span class="mt-1.5 block font-mono text-[7px] text-[#9bbc79]">{item.tasks.filter((task) => task.status === "running").length} running · {item.tasks.length} cards</span></button>{/each}</div></aside>
		<section class="min-h-0 overflow-auto p-4 sm:p-5">{#if board}<div class="mx-auto flex min-w-[980px] max-w-[1680px] flex-col gap-4"><div class="flex items-end justify-between gap-4"><div><h2 class="m-0 text-[18px] font-semibold tracking-[-.025em] text-[#ecf3f4]">{board.name}</h2><p class="mt-1 mb-0 flex items-center gap-1.5 font-mono text-[8px] text-[#74868c]"><FolderGit2 size={10} /> {board.workspaceRoot}</p></div><form class="flex items-center gap-2" onsubmit={(event) => { event.preventDefault(); void addTask(); }}><input bind:value={taskTitle} maxlength="160" placeholder="Capture a task..." class="h-10 w-60 rounded-xl border border-[#34444c] bg-[#0b1217] px-3 text-[10px] text-white outline-none placeholder:text-[#5e7077] focus:border-[#839d66]" /><button type="submit" class="flex h-10 items-center gap-1.5 rounded-xl border border-[rgba(199,246,125,.45)] bg-[linear-gradient(135deg,#648a3f,#3f5f2d)] px-3.5 font-mono text-[9px] font-semibold text-[#f0ffdf] shadow-[0_10px_24px_rgba(93,139,54,.18)] transition hover:-translate-y-0.5"><Plus size={12} /> Add task</button></form></div><div class="grid grid-cols-7 gap-2.5">{#each columns as column (column.id)}<div role="list" aria-label={column.label} class="min-h-[460px] rounded-2xl border border-[#27363d] bg-[rgba(10,17,21,.76)] p-2.5" ondragover={(event) => event.preventDefault()} ondrop={() => { if (draggedTaskId) void moveTask(draggedTaskId, column.id); draggedTaskId = ""; }}><div class="mb-3 flex items-center gap-2 px-1"><span class={`h-1.5 w-1.5 rounded-full ${column.accent}`}></span><span class="font-mono text-[8px] tracking-[.11em] text-[#a6b4b7] uppercase">{column.label}</span><span class="ml-auto rounded-full bg-[#1a272d] px-1.5 py-0.5 font-mono text-[7px] text-[#70848a]">{board.tasks.filter((task) => task.status === column.id).length}</span></div><div class="space-y-2">{#each board.tasks.filter((task) => task.status === column.id) as task (task.id)}<button draggable="true" type="button" class={`group relative w-full rounded-xl border p-2.5 text-left shadow-[0_8px_18px_rgba(0,0,0,.16)] transition hover:-translate-y-0.5 hover:border-[#60777d] ${task.status === "done" ? "border-[#294536] bg-[#0d1a14]" : task.status === "running" ? "border-[rgba(142,218,126,.45)] bg-[linear-gradient(145deg,rgba(45,83,47,.55),rgba(15,29,22,.95))]" : "border-[#35454c] bg-[#111a1f]"}`} ondragstart={() => draggedTaskId = task.id} onclick={() => selectedTaskId = task.id}><GripVertical size={11} class="absolute top-2.5 right-1.5 text-[#52636a] opacity-0 transition group-hover:opacity-100" /><span class={`inline-flex rounded-full border px-1.5 py-0.5 font-mono text-[6px] tracking-[.08em] uppercase ${task.kind === "fix" ? "border-[#82504d] bg-[#2c1718] text-[#e9a09b]" : task.kind === "research" ? "border-[#4f7090] bg-[#112231] text-[#a8d1f0]" : "border-[#536c42] bg-[#172417] text-[#bada96]"}`}>{kindLabel(task.kind)}</span><strong class="mt-2 block pr-2 text-[10px] leading-[1.42] text-[#e4ecee]">{task.title}</strong>{#if task.targetMinutes}<span class="mt-2 flex items-center gap-1 font-mono text-[7px] text-[#b7c982]"><CalendarClock size={9} /> target {task.targetMinutes}m</span>{/if}{#if task.status === "done"}<span class="mt-2 flex items-center gap-1 font-mono text-[7px] text-[#86ca94]"><Check size={9} /> verified</span>{/if}</button>{/each}{#if column.id === "running" && !board.tasks.some((task) => task.status === "running")}<div class="rounded-xl border border-dashed border-[#32453b] px-2 py-4 text-center"><Sparkles size={13} class="mx-auto text-[#779b70]" /><p class="mt-1.5 mb-0 font-mono text-[7px] leading-[1.5] text-[#667b70]">Run a ready task to see live activity here.</p></div>{/if}</div></div>{/each}</div></div>{/if}</section>
	</div>
	{#if selectedTask}<div class="fixed inset-0 z-50 flex justify-end bg-black/55 backdrop-blur-[2px]"><div class="h-full w-[min(470px,94vw)] overflow-y-auto border-l border-[#34444b] bg-[#0c1419] p-5 shadow-[-24px_0_70px_rgba(0,0,0,.42)]" role="dialog" aria-modal="true" aria-label="Task details"><button type="button" class="ml-auto block rounded-lg border border-[#34444b] px-2 py-1 font-mono text-[8px] text-[#a8b7ba] hover:text-white" onclick={() => selectedTaskId = ""}>Close</button><p class="mt-4 mb-0 font-mono text-[8px] tracking-[.14em] text-[#89ad71] uppercase">{kindLabel(selectedTask.kind)} task</p><h2 class="mt-2 mb-4 text-[18px] text-white">{selectedTask.title}</h2><label class="block"><span class="mb-1.5 block font-mono text-[8px] text-[#83959b] uppercase">Task brief</span><textarea bind:value={draftPrompt} rows="8" placeholder="Describe the work, expected result, and verification..." class="w-full rounded-xl border border-[#34444b] bg-[#080e12] p-3 text-[10px] leading-[1.55] text-[#dce6e8] outline-none focus:border-[#73905d]"></textarea></label><div class="mt-4 grid grid-cols-2 gap-2"><div class="rounded-xl border border-[#2f4046] bg-[#091116] p-3"><span class="font-mono text-[7px] text-[#71858a] uppercase">Workspace</span><p class="mt-1 mb-0 break-all text-[9px] text-[#d6e1e3]">{selectedTask.workspaceRoot}</p></div><div class="rounded-xl border border-[#2f4046] bg-[#091116] p-3"><span class="font-mono text-[7px] text-[#71858a] uppercase">Reasoning</span><p class="mt-1 mb-0 text-[10px] capitalize text-[#d6e1e3]">{selectedTask.reasoning}</p></div></div><p class="mt-4 mb-0 rounded-xl border border-[#4a3e29] bg-[#20190f] p-3 text-[9px] leading-[1.6] text-[#d7bd85]">Task editing, model settings, schedule, and real execution are the next persisted card controls. This starter board already persists card state and drag/drop status changes.</p></div></div>{/if}
</div>
